import Synchronization
let head = Atomic<Int>(0), tail = Atomic<Int>(0)   // tickets for a bounded ring
func push(_ v: Int) -> Bool {                       // producer
  let t = tail.load(ordering: .relaxed)
  guard t - head.load(ordering: .acquiring) < capacity else { return false }
  slots[t % capacity] = v                           // payload first...
  tail.store(t + 1, ordering: .releasing)           // ...then publish the ticket
  return true
}

